\begin{defish}
  \emph{Na\"{i}ve Comprehension.} $\Setabs{x}{\phi(x)}$ exists for any formula $\phi$.
\end{defish}

target:
\begin{defish}
  \emph{ساده ادراک۔} د هر فارمول $\phi$ لپاره $\Setabs{x}{\phi(x)}$ وجود لري۔
\end{defish}

source:
\begin{thm}[Russell's Paradox]
There is no set $R = \Setabs{x}{x \notin x}$
\end{thm}

target:
\begin{thm}[د رسل تناقض]
سټ $R = \Setabs{x}{x \notin x}$ نشت۔
\end{thm}

source:
\begin{proof}
If $R = \Setabs{x}{x \notin x}$ exists, then
$R \in R$ iff $R \notin R$, which is a contradiction.
\end{proof}

target:
\begin{proof}
که $R = \Setabs{x}{x \notin x}$ وجود ولري، نو
$R \in R$ که او يوازې که $R \notin R$، چې دا تناقض دے۔
\end{proof}

source:
\begin{defish}
\emph{Predicative Comprehension.} For every formula $\phi$ quantifying only over sets: the set$^\prime$ $\Setabs{x}{\phi(x)}$ exists.
\end{defish}

target:
\begin{defish}
\emph{پريديکاتيف ادراک۔} د هر فارمول $\phi$ لپاره چې يوازې پر سټونو کمي کول کوي: سټ$^\prime$ $\Setabs{x}{\phi(x)}$ وجود لري۔
\end{defish}

